import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int HPY = sc.nextInt();
        int ATKY = sc.nextInt();
        int DEFY = sc.nextInt();

        int HPM = sc.nextInt();
        int ATKM = sc.nextInt();
        int DEFM = sc.nextInt();

        int hCost = sc.nextInt();
        int aCost = sc.nextInt();
        int dCost = sc.nextInt();

        int minCost = Integer.MAX_VALUE;

        // Upper bounds for additional ATK and DEF
        // ATK: enough to do at least 1 damage and not too large
        // DEF: enough to reduce monster damage to 0
        for (int addAtk = 0; addAtk <= 200; addAtk++) {
            int curAtk = ATKY + addAtk;
            int damageToMonster = Math.max(0, curAtk - DEFM);
            if (damageToMonster == 0) continue; // can't win if no damage

            for (int addDef = 0; addDef <= 200; addDef++) {
                int curDef = DEFY + addDef;
                int damageToYang = Math.max(0, ATKM - curDef);

                // Rounds needed to kill monster
                int roundsToKillMonster = (HPM + damageToMonster - 1) / damageToMonster;

                // HP Yang needs to survive these rounds
                int neededHP;
                if (damageToYang == 0) {
                    neededHP = 1; // any positive HP is enough
                } else {
                    neededHP = roundsToKillMonster * damageToYang + 1;
                }

                int addHP = Math.max(0, neededHP - HPY);

                int cost = addHP * hCost + addAtk * aCost + addDef * dCost;
                if (cost < minCost) {
                    minCost = cost;
                }
            }
        }

        System.out.println(minCost);
    }
}

