        int DEFM = sc.nextInt();

        int h = sc.nextInt();
        int a = sc.nextInt();
        int d = sc.nextInt();

        int minCost = Integer.MAX_VALUE;

        // Upper bounds for brute force
        int maxAtk = 200; // ATKY up to 100, add up to 100
        int maxDef = 200; // DEFY up to 100, add up to 100

        for (int newAtk = ATKY; newAtk <= maxAtk; newAtk++) {
            for (int newDef = DEFY; newDef <= maxDef; newDef++) {
                int damageToMonster = Math.max(0, newAtk - DEFM);
                if (damageToMonster == 0) continue; // can't win if can't damage monster

                int turnsToKillMonster = (HPM + damageToMonster - 1) / damageToMonster;

                int damageToYang = Math.max(0, ATKM - newDef);
                int yangHpNeeded;
                if (damageToYang == 0) {
                    yangHpNeeded = 1; // any positive HP is enough
                } else {
                    yangHpNeeded = damageToYang * (turnsToKillMonster - 1) + 1;
                }

                int extraHp = Math.max(0, yangHpNeeded - HPY);
                int extraAtk = newAtk - ATKY;
                int extraDef = newDef - DEFY;

                int cost = extraHp * h + extraAtk * a + extraDef * d;
                if (cost < minCost) {
                    minCost = cost;
                }
            }
        }

        System.out.println(minCost);
